css:
.print-format { font-size: 11px; color: #000; }
.dz-head { display: flex; justify-content: space-between; gap: 16px; border-bottom: 2px solid #000; padding-bottom: 8px; margin-bottom: 10px; }
.dz-head .seller .name { font-size: 16px; font-weight: 700; }
.dz-head .doc-title { text-align: right; }
.dz-head .doc-title h2 { margin: 0; font-size: 20px; letter-spacing: .05em; }
.dz-ids { font-size: 10px; line-height: 1.5; }
.dz-parties { display: flex; gap: 16px; margin-bottom: 10px; }
.dz-box { flex: 1; border: 1px solid #000; padding: 6px 8px; }
.dz-box .title { font-size: 9px; text-transform: uppercase; letter-spacing: .05em; margin-bottom: 3px; }
table.dz-items { width: 100%; border-collapse: collapse; }
table.dz-items th, table.dz-items td { border: 1px solid #000; padding: 4px 6px; }
table.dz-items th { background: #eee; font-size: 10px; text-transform: uppercase; }
table.dz-items td.num, table.dz-items th.num { text-align: right; white-space: nowrap; }
.dz-totals { width: 45%; margin-left: auto; margin-top: 8px; border-collapse: collapse; }
.dz-totals td { padding: 3px 6px; border: 1px solid #000; }
.dz-totals td.num { text-align: right; white-space: nowrap; }
.dz-totals tr.grand td { font-weight: 700; font-size: 13px; }
.dz-words { margin-top: 8px; font-style: italic; }
.dz-foot { display: flex; justify-content: space-between; gap: 16px; margin-top: 14px; }
.dz-stamp { width: 45%; height: 80px; border: 1px dashed #000; padding: 6px; font-size: 9px; text-transform: uppercase; }
.dz-note { font-size: 10px; margin-top: 8px; }
.dz-watermark { position: fixed; top: 40%; left: 10%; font-size: 64px; font-weight: 700; color: rgba(200,0,0,.25); transform: rotate(-30deg); z-index: 0; }
